            holiday_records = []

            for i, item in enumerate(raw_holidays):
                if i >= 365:
                    break

                current_date = start_date + timedelta(days=i)
                date_str = current_date.strftime('%m-%d')
                day_num = i + 1

                title, emoji, tint, description, mission = item
                holiday_records.append((title, emoji, tint, description, mission, date_str, day_num, 1))

            cursor.executemany('''
                INSERT INTO holidays (title, emoji, tint, description, mission, show_date, day_number, active)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            ''', holiday_records)
            logger.info("База успешно заполнена: все 365 дней строго на своих местах!")

